import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // Plane geometry (7×6 units) – static backdrop style
  const geometry = new PlaneGeometry(7, 6);

  // Basic node material (no lighting needed for static composition)
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
  });

  // Mesh
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture asynchronously; material updates when ready
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Event handlers placeholder (none for this node)
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (material.map && typeof material.map.dispose === 'function') {
      material.map.dispose();
    }
    // Kill any GSAP timelines that might be stored (none in this node)
    if (root.userData._timelines) {
      root.userData._timelines.forEach((tl) => tl.kill());
    }
  };

  return root;
}
